	seaRadius         = 360
	sector            = 8
	unitMilli         = 1000
	sectorMilli       = 8000
	mouthAlignNum     = 552264
	mouthContact      = 1000
	healsPerDay       = 2
	healPercent       = 40
	healCooldownMs    = 8 * 3600 * 1000
	ictOffsetMs       = 7 * 3600 * 1000
	dayMs             = 24 * 3600 * 1000
	springPeriodMs    = 20000
	springLifeMs      = 15000
	springRadiusMilli = 3000
	springHealPercent = 20
	shelterHPMax      = 64
	shelterRebuildMs  = 20000
	burstWindowMs     = 1000
	burstCoolMs       = 2000
