}

type disc struct {
	x     int
	z     int
	r     int
	inner int
	kind  string
}

var (
	cheers      []cheerRow
	claims      []claimRow
	watches     []watchRow
	killSeq     int
	shelterHP   []int
	shelterDown []int64
	shelterTable = []disc{
		{x: 96_000, z: 8_000, inner: 5_200, kind: "reef"},
		{x: -120_000, z: 72_000, inner: 5_600, kind: "reef"},
