)

const (
	denom        = "ugnot"
	ugnot        = 1_000_000
	mintFee      = 5 * ugnot
	layFee       = 2 * ugnot
	upgradeFee   = 15 * ugnot
	protocolBps  = 200
	maxRoyalty   = 1000
	maxPrice     = 1_000_000 * ugnot
	combatLockMs = 5000
	layBlocks    = 2
	listCap      = 50
)

type fishBody struct {
	id              int
	name            string
	rarity          string
	species         string
